--
-- Name: v_subscriber_details; Type: VIEW; Schema: public; Owner: billing_user
--

CREATE VIEW public.v_subscriber_details AS
 SELECT s.last_name AS "Фамилия",
    s.first_name AS "Имя",
    s.phone_number,
    c.call_date,
    c.destination_number,
    st.service_type_id AS "Тип услуги",
    c.cost,
    c.duration_seconds
   FROM ((public.subscribers s
     JOIN public.call_records c ON ((s.subscriber_id = c.subscriber_id)))
     JOIN public.service_types st ON ((c.service_type_id = st.service_type_id)));


ALTER TABLE public.v_subscriber_details OWNER TO billing_user;

--
-- Name: v_subscriber_finances; Type: VIEW; Schema: public; Owner: billing_user
--

CREATE VIEW public.v_subscriber_finances AS
 SELECT s.first_name,
    s.last_name,
    s.phone_number,
    tp.plan_name,
    tp.monthly_fee,
    s.balance
   FROM (public.subscribers s
     LEFT JOIN public.tariff_plans tp ON ((s.plan_id = tp.plan_id)));


ALTER TABLE public.v_subscriber_finances OWNER TO billing_user;

